  function stats(){const h=state.hero,r=state.race.mods,e=equippedStats();const out={maxHp:h.baseHp+r.hp+((state.citadel?.barracks||0)*6),attack:Math.floor((h.baseAttack+r.str+e.attack+skillRank("warrior_edge")*2)*(1+([0,.05,.10,.20][Math.min(3,state.citadel?.forge||0)]||0)))+((state.mercenaries||0)*2)+((RPG_DB.pets.find(p=>p.id===state.petId)?.buff.attack)||0)+((state.altarBuff&&state.altarBuff.charges>0)?(state.altarBuff.attack||0):0),defense:h.baseDefense+e.defense+skillRank("warrior_guard")*2+((state.altarBuff&&state.altarBuff.charges>0)?(state.altarBuff.defense||0):0),dodge:clamp(h.baseDodge+r.dodge+skillRank("rogue_dodge")*3+((RPG_DB.pets.find(p=>p.id===state.petId)?.buff.dodge)||0),0,45),crit:clamp(h.baseCrit+r.crit+skillRank("rogue_crit")*4+((state.altarBuff&&state.altarBuff.charges>0)?(state.altarBuff.crit||0):0),0,80),maxMp:30+Math.floor(h.level*4)+(r.str<0?4:0)+skillRank("mage_power")*5};if((state.injuries||[]).includes("rib")){out.attack=Math.max(1,out.attack-2);out.defense=Math.max(0,out.defense-1);}if((state.injuries||[]).includes("fear"))out.crit=Math.max(0,out.crit-4);return out;}
