  function updateTop(){if(!state.hero)return;const h=state.hero,s=stats();$("top-hp").textContent=`${h.hp}/${s.maxHp}`;$("top-gold").textContent=h.gold;$("top-level").textContent=h.level;$("top-karma").textContent=(h.karma>0?"+":"")+h.karma;$("top-hp-bar").style.width=`${h.hp/s.maxHp*100}%`;}
